--- داده‌های در دسترس (فقط همین‌ها مبنا هستند؛ عدد بیرون از این‌ها اختراع نشود) ---
```json
{
  "data_catalog": [
    {
      "dataset": "defect_log",
      "description": "ثبت عیوب تولید به تفکیک خط و نوع عیب",
      "dimensions": [
        "line",
        "defect_type",
        "month"
      ],
      "measures": [
        "units",
        "defect_count"
      ]
    },
    {
      "dataset": "inspection_results",
      "description": "نتیجهٔ بازرسی کیفی محصول",
      "dimensions": [
        "product",
        "month"
      ],
      "measures": [
        "produced",
        "passed",
        "failed"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "defect_rate",
      "description": "نرخ عیب تولید",
      "formula": "تعداد عیب تقسیم بر تعداد تولید",
      "unit": "درصد",
      "dimensions": [
        "line"
      ]
    },
    {
      "metric": "first_pass_yield",
      "description": "بازده عبور اول",
      "formula": "تعداد سالم در اولین بار تقسیم بر کل تولید",
      "unit": "درصد",
      "dimensions": [
        "line"
      ]
    }
  ],
  "business_context": [
    "هدف سالانهٔ کاهش نرخ عیب یک واحد درصد",
    "تأمین مواد اولیه از دو تأمین‌کنندهٔ داخلی و یک خارجی",
    "سفارش‌های صادراتی با الزام‌های کیفی سخت‌گیرانه"
  ]
}
```

برای پاسخ دقیق، این داده را استخراج می‌کنم:
```json
{
  "tool": "get_dataset",
  "arguments": {
    "name": "defect_log",
    "filters": {
      "period": "this_month"
    }
  }
}
```

